import java.util.*;

class Solution {
    public int numSubmatrixSumTarget(int[][] matrix, int target) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        return rows <= cols ? countByRowPairs(matrix, target) : countByColumnPairs(matrix, target);
    }

    private int countByRowPairs(int[][] matrix, int target) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        int answer = 0;
        for (int top = 0; top < rows; top++) {
            int[] columnSums = new int[cols];
            for (int bottom = top; bottom < rows; bottom++) {
                for (int col = 0; col < cols; col++) columnSums[col] += matrix[bottom][col];
                answer += countSubarraysWithTarget(columnSums, target);
            }
        }
        return answer;
    }

    private int countByColumnPairs(int[][] matrix, int target) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        int answer = 0;
        for (int left = 0; left < cols; left++) {
            int[] rowSums = new int[rows];
            for (int right = left; right < cols; right++) {
                for (int row = 0; row < rows; row++) rowSums[row] += matrix[row][right];
                answer += countSubarraysWithTarget(rowSums, target);
            }
        }
        return answer;
    }

    private int countSubarraysWithTarget(int[] values, int target) {
        Map<Integer, Integer> prefixCounts = new HashMap<>();
        prefixCounts.put(0, 1);
        int prefix = 0;
        int count = 0;
        for (int value : values) {
            prefix += value;
            count += prefixCounts.getOrDefault(prefix - target, 0);
            prefixCounts.put(prefix, prefixCounts.getOrDefault(prefix, 0) + 1);
        }
        return count;
    }
}

