class Solution {
    public int numSubmatrixSumTarget(int[][] matrix, int target) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        int[][] prefix = new int[rows + 1][cols + 1];
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                prefix[row + 1][col + 1] = matrix[row][col]
                        + prefix[row][col + 1]
                        + prefix[row + 1][col]
                        - prefix[row][col];
            }
        }

        int count = 0;
        for (int top = 0; top < rows; top++) {
            for (int left = 0; left < cols; left++) {
                for (int bottom = top; bottom < rows; bottom++) {
                    for (int right = left; right < cols; right++) {
                        int sum = prefix[bottom + 1][right + 1]
                                - prefix[top][right + 1]
                                - prefix[bottom + 1][left]
                                + prefix[top][left];
                        if (sum == target) count++;
                    }
                }
            }
        }
        return count;
    }
}

import java.util.*;

class Solution {
    public int numSubmatrixSumTarget(int[][] matrix, int target) {
        int rows = matrix.length;
        int cols = matrix[0].length;
        int answer = 0;
        for (int top = 0; top < rows; top++) {
            int[] columnSums = new int[cols];
            for (int bottom = top; bottom < rows; bottom++) {
                for (int col = 0; col < cols; col++) columnSums[col] += matrix[bottom][col];
                answer += countWithCompressedPrefixes(columnSums, target);
            }
        }
        return answer;
    }

    private int countWithCompressedPrefixes(int[] values, int target) {
        int[] prefixes = new int[values.length + 1];
        for (int i = 0; i < values.length; i++) prefixes[i + 1] = prefixes[i] + values[i];
        int[] sorted = prefixes.clone();
        Arrays.sort(sorted);
        int uniqueSize = 0;
        for (int value : sorted) {
            if (uniqueSize == 0 || sorted[uniqueSize - 1] != value) sorted[uniqueSize++] = value;
        }
        int[] unique = Arrays.copyOf(sorted, uniqueSize);
        int[] frequencies = new int[uniqueSize];
        int count = 0;
        for (int prefix : prefixes) {
            int need = lowerBound(unique, prefix - target);
            if (need < unique.length && unique[need] == prefix - target) count += frequencies[need];
            int index = lowerBound(unique, prefix);
            frequencies[index]++;
        }
        return count;
    }

    private int lowerBound(int[] values, int target) {
        int lo = 0;
        int hi = values.length;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (values[mid] < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}
